CREATE TABLE access_frozen_scopes (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging','purged')), PRIMARY KEY(workspace_id,project_id));
CREATE TABLE access_purge_bypass (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(workspace_id,project_id));
CREATE TRIGGER access_freeze_oauth_forms_insert BEFORE INSERT ON access_oauth_forms WHEN EXISTS(SELECT 1 FROM access_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='')) AND NOT EXISTS(SELECT 1 FROM access_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='')) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER access_freeze_oauth_forms_update BEFORE UPDATE ON access_oauth_forms WHEN (EXISTS(SELECT 1 FROM access_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='')) AND NOT EXISTS(SELECT 1 FROM access_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id=''))) OR (EXISTS(SELECT 1 FROM access_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='')) AND NOT EXISTS(SELECT 1 FROM access_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id=''))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
